import pytest
from fastapi import APIRouter, FastAPI
from fastapi.routing import APIRoute
from fastapi.testclient import TestClient


def test_rate_limit_metadata():
    app = FastAPI()

    @app.get("/limited", rate_limit="50/minute")
    def limited():
        return {"message": "limited"}

    @app.get("/unlimited")
    def unlimited():
        return {"message": "unlimited"}

    response = TestClient(app).get("/openapi.json")
    assert response.status_code == 200
    paths = response.json()["paths"]
    assert paths["/limited"]["get"]["x-rate-limit"] == "50/minute"
    assert "x-rate-limit" not in paths["/unlimited"]["get"]


@pytest.mark.parametrize(
    "method", ["get", "post", "put", "delete", "options", "head", "patch", "trace"]
)
@pytest.mark.parametrize("use_router", [False, True])
def test_rate_limit_decorators(method: str, use_router: bool):
    app = FastAPI()
    router = APIRouter()
    target = router if use_router else app

    @getattr(target, method)("/limited", rate_limit="1000/hour")
    def limited():
        return {"message": "limited"}

    if use_router:
        parent = APIRouter()
        parent.include_router(router, prefix="/nested")
        app.include_router(parent, prefix="/api")
    path = "/api/nested/limited" if use_router else "/limited"
    response = TestClient(app).get("/openapi.json")
    assert response.status_code == 200
    assert response.json()["paths"][path][method]["x-rate-limit"] == "1000/hour"


@pytest.mark.parametrize("use_router", [False, True])
def test_rate_limit_api_route(use_router: bool):
    app = FastAPI()
    router = APIRouter()
    target = router if use_router else app

    @target.api_route("/limited", methods=["GET"], rate_limit="100/minute")
    def limited():
        return {}

    if use_router:
        app.include_router(router)
    response = TestClient(app).get("/openapi.json")
    assert response.json()["paths"]["/limited"]["get"]["x-rate-limit"] == "100/minute"


@pytest.mark.parametrize("rate_limit", [None, "", "50/minute"])
def test_rate_limit_api_route_constructor(rate_limit: str | None):
    def endpoint():
        return {}

    route = APIRoute("/limited", endpoint, rate_limit=rate_limit)
    assert route.rate_limit == rate_limit
    app = FastAPI(routes=[route])
    operation = TestClient(app).get("/openapi.json").json()["paths"]["/limited"]["get"]
    if rate_limit is None:
        assert "x-rate-limit" not in operation
    else:
        assert operation["x-rate-limit"] == rate_limit

